import React, { PropsWithChildren } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

/** @internal */
export interface EmojiShapeProps {
  active?: boolean;
  label?: string;
}

const StyledEmojiShape = /* @__PURE__ */ styled('span')<{
  $active: boolean;
}>(({ $active }) => ({
  border: $active ? `1px solid ${Colors.Text.Neutral.Default}` : 'none',
  borderRadius: '4px',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '100%',
  height: '100%',
  boxSizing: 'border-box',
}));

export const EmojiShape = ({
  active = false,
  label = 'emojiShape',
  children,
}: PropsWithChildren<EmojiShapeProps>) => {
  return (
    <StyledEmojiShape role="img" aria-labelledby={label} $active={active}>
      {children}
    </StyledEmojiShape>
  );
};

EmojiShape['displayName'] = 'EmojiShape';
